#   ради чего его зовут («рынок: 0 предметов»). Флаг on_square;
#   (б) ЖЁСТКИЕ СЛОТЫ «через 45/90/120 градусов» не работают там, где четверть
#   окружности лежит на полосе улицы: слот пропадал молча. Развёртка по углу и
#   карта свободы клетками 1 м — набор садится по убыванию свободного радиуса.
#   (5) ОЗЕЛЕНЕНИЕ: 49 кустов полки glade вдоль глухих стен и у ворот, не
#   больше двух на дом, не ближе 1.2 м к дверной грани. Ассеты СУЩЕСТВУЮЩИЕ и
#   не правлены (табу владельца).
#   (6) РАЗНООБРАЗИЕ СВЕТА: таблица LIGHT из шести ТИПОВ источника вместо
#   одного HEARTH_COLOR на всё — жаровня (ярко-оранжевая R10, softness 0.20),
#   горн (R6.5, 0.15), очаг (по залу, 0.25), фонарь-столб (тёплый белый R7,
#   0.60), фонарь у двери (тусклый R4.5, 0.50), огонь площади (R8.5, 0.65).
#   Ключ softness заведён владельцем (661d4bf) и пишется в [light]. Тела —
#   furn-lamp-post/-s (11 столбов шагом 16 м в шахматном порядке) и
#   furn-lamp-wall (19 настенных у дверей); точка света берётся из ЛОКАЛЬНЫХ
#   координат рецепта и поворачивается матрицей сцены — «свет над столбом»
#   мировой прибавкой был бы четвёртым повторением одной и той же ошибки.
#   (7) ВТОРОЙ ПРОХОД ЗАМКНУТ В КОНВЕЙЕРЕ (WHITERUN_WRITE_HEIGHTS). Схема
#   «gen -> dump_heights -> gen» описана с 21.08, но прибора, который пишет
#   /tmp/whiterun_heights.txt, в дереве НЕТ НИ ОДНОГО: дамп остался снимком
#   разовой руки, и любой сдвиг дома делал его ложью. Именно на этом
#   check_floors дал «протыкает пол на 0.75 м» у домов, стоящих верно.
# - 23:08:2026 - 23:55:00: ДОМ СТОИТ НА ФУНДАМЕНТЕ, А НЕ В ЯМЕ (КРИТИЧЕСКИЙ
#   заказ владельца 23.08 дословно: «дома почти все на треть первого этажа под
#   землей — это крит! земля не ровная, дома ровные; чтобы избегать налезания
#   земли на дома, необходимо делать каждому дому небольшой фундамент, который
#   может уходить под землю, но сам дом на нём стоит как на ровной земле; а к
#   двери в дом идёт лестница-ступеньки»).
#   (0) ПОЧЕМУ ПРИЁМКА ЭТОГО НЕ ВИДЕЛА — ДВЕ РАЗНЫЕ ОШИБКИ, И ОБЕ ПРО МЕРУ.
#   (а) check_floors меряет ground() — сетку PLAN_H, из которой пад и вырезан;
#   она отвечает «легло ли задуманное в задуманное», а стену пачкает то, что
#   ПОСТРОЕНО. Написан прибор по ЗЕМЛЕ ДВИЖКА: tools/probe_ground.cpp грузит
#   сцену вместе с .relief (dfn_scene_check --ground кладёт в мир только пады и
#   реки — для Вайтрана, чья форма почти вся в relief, это ДРУГОЙ город) и
#   отвечает terrain_height в любой точке.
#   (б) ...и он немедленно нашёл расхождение до 0.40 м под домами. Причина —
#   /tmp/whiterun_natural.txt, от которого считаются ВСЕ дельты relief: в дереве
#   НЕТ НИ ОДНОЙ строки, которая его пишет (поиск по репозиторию даёт одно
#   чтение — здесь). Тот же снимок разовой руки, что был у поля высот до 24.08,
#   только ценой не одной посадки, а всего рельефа: свежий замер против
#   лежавшего снимка дал медиану 0.003 м, 95% 0.109, МАКСИМУМ 0.481. Натуральная
#   земля стала параметром (WHITERUN_NATURAL), пишется прибором по выпуску
#   WHITERUN_BARE=1, и после этого PLAN_H сходится с движком: медиана 0.002,
#   95% 0.007 м.
#   (1) КРИТ ДОКАЗАН ЧИСЛОМ, а не пересказан. Прибор по земле движка, пятно
#   СТЕН (вершины нижнего венца .dfh, а не габарит со свесом кровли), шаг проб
#   <= 1 м, контрольная рука WHITERUN_PAD=1 (прежняя посадка из того же
#   генератора):
#     ДО:  земля выше низа стен у 26 из 26 домов; худшие +1.63 (ЗАМОК),
#          +1.23 (МЕЛЬНИЦА), +0.56 (таверна), +0.55 (усадьба).
#          В МЕТРЕ от стены — 26 из 26, медиана +0.17, худший +2.50; в двух
#          метрах медиана +0.76.
#     ПОСЛЕ: 0 из 26, худший -0.07 м (это и есть заказанный зазор).
#   Число «в метре от стены» важнее числа «на стене»: пад РАБОТАЛ внутри пятна
#   (check_floors честно давал 26 из 26), но он КОРЫТО — срез ровно по пятну с
#   каймой 1.2 м, а вокруг остаётся склон, и в кадре у дома на склоне кровля
#   садится прямо в траву.
#   (2) ПОСАДКА ПО МАКСИМУМУ, А НЕ ПО МИНИМУМУ, И ПАД СНЯТ. Отметка низа стен =
#   max(земля под пятном стен) + 0.08. Минимум был честен ровно в одном («ни
#   один угол не висит»), но выбирал нижнюю точку склона. Максимум переворачивает
#   вопрос: висеть теперь может ВСЁ, и держит это не земля, а лента.
#   (3) ЛЕНТА ФУНДАМЕНТА по периметру пятна стен из city-foot2-hNN (выпечка
#   кузни): верх на отметке низа стен, низ до min(земля) - 0.30, высота ОДНА на
#   весь периметр — на склоне верх горизонтален, низ уходит в грунт. Наружная
#   плоскость на 0.15 за лицо стены (цоколь читается выступом), углы закрыты
#   продлением сторон на полтолщины. Глубже потолка ряда (4 м) — ВЕНЦАМИ, а не
#   новыми рецептами: просит это один донжон на кромке замкового плато, под чьим
#   пятном 4.4x4.4 перепад 9.3 м.
#   (4) КРЫЛЬЦО из city-stoop16-hNN там, где перепад «земля -> порог» > 0.20 м
#   (15 домов из 26): подступенок 0.150..0.200, проступь ровно 0.30, ширина 1.6.
#   Верх целится в порог ТОЧНО, остаток ряда уходит в подошву — наверху игрок
#   сходит с марша на ходу. Ходить по нему есть чем: fill=6 + open=2 строит
#   НЕВИДИМЫЙ ПАНДУС (HouseStairs.cpp, 51c8fbb).
#   (5) ПОЛОТНО ДОРОЖКИ ЦЕЛИТСЯ В ПОДНОЖИЕ МАРША, А НЕ В ПОРОГ: порог теперь
#   стоит выше земли, и полотно — свойство ЗЕМЛИ — рисовало бы мостовую по
#   склону насыпи под лестницей.
#   (6) РУСЛО ИСКЛЮЧЕНО ИЗ ПРОБ И ИЗ ЛЕНТЫ. Вырез дна делает движок, а дельты
#   чертежа в коридоре гасит river_taper, поэтому PLAN_H показывает там берег,
#   которого под мельницей нет: её пятно стоит НАД лотком. Лента до дна
#   перегородила бы русло стеной в четыре с половиной метра, а колесу нужна вода.
#   (7) НИЗ ЛЕНТЫ — В ЗАПИСИ ДОМА, А НЕ В СЛОВАРЕ ПО ИМЕНИ. Первая редакция
#   держала его в dict[имя], и приёмка врала на весь город: имён 26 на 26 домов,
#   но РАЗНЫХ среди них 12. Поймано не рассуждением, а числом: «глубже всех
#   -7.29 м» при потолке ленты 4.0 арифметически невозможно ни при какой посадке.
#   ПРИЁМКА (check_footings, парная и по обоим приборам): утоплено 0 из 26,
#   висит 0 из 26; худшая утопленность -0.07 (движок) / -0.08 (PLAN_H), худший
#   вкоп -0.29 / -0.30. check_floors 26 из 26, мебель 205 из 205.
import json
import math
import os
import re
import shutil

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
PLAN = json.load(open(os.path.join(ROOT, "docs/WHITERUN_PLAN.json"), encoding="utf-8"))

# --- ИМЯ ВЫПУСКА: DFN_GEN_OUT ------------------------------------------------
# Боевые файлы города (whiterun.scene/.relief/.map) — ОБЩИЙ предмет: по ним
# ходит критик, их открывает владелец. Пока идёт волна правок, перезапись
# боевого выпуска отнимает у смотрящего предмет прямо под ногами, а его отчёт
# начинает описывать город, которого уже нет. Поэтому имя выпуска — параметр:
#     DFN_GEN_OUT=whiterun-dev python3 tools/gen_whiterun.py
# кладёт assets/scenes/whiterun-dev.scene(+.relief) и
# assets/maps/houses/whiterun-dev.map; смотреть — DFN_OPEN_MAP=houses/whiterun-dev.
# Умолчание «whiterun» оставлено НАМЕРЕННО: боевая перегенерация не должна
# требовать помнить лишнее слово, а вот черновая — должна называть себя.
OUT = os.environ.get("DFN_GEN_OUT", "whiterun")

H = []   # [house]
P = []   # [place]
LIGHTS = []   # [light]

def house(file, x, y, z, yaw_deg, note):
    H.append((f"assets/houses/{file}", x, y, z, math.radians(yaw_deg), note))

def place(obj, x, y, z, yaw_deg=0.0, note=None):
    P.append((obj, x, y, z, math.radians(yaw_deg), note))

# --- ПАЛИТРА ГОРОДСКОГО ОГНЯ (заказ владельца 22.08: «от фонарей свет скудный,
# надо разнообразных источников с разным уровнем яркости и мягкости») ---------
# Ключ [light].softness заведён в движок владельцем (661d4bf): 0 — прежний
# резкий факельный профиль, 1 — свет огибает формы (wrap-диффуз) и затухает
# полого. Разметка его же словами, и она НЕ КОСМЕТИКА, а описание источника:
# у живого пламени короткая жёсткая тень, у фонаря со стеклом рассеиватель, у
# окна светит вся плоскость проёма.
#   ИСТОЧНИК                цвет               радиус  мягкость
#   жаровня (открытый огонь) ярко-оранжевый     10.0    0.20
#   горн кузницы            оранжево-красный     6.5    0.15
#   очаг в доме             тёплый глубокий      по залу 0.25
#   фонарь-столб            тёплый белый         7.0    0.60
#   фонарь у двери          тусклый тёплый       4.5    0.50
#   огонь сквера/двора      тёплый белый ярче    8.5    0.65
LIGHT = {
    "brazier":  ((1.00, 0.48, 0.16), 10.0, 0.20),
    "forge":    ((1.00, 0.40, 0.12),  6.5, 0.15),
    "hearth":   ((1.00, 0.52, 0.20),  0.0, 0.25),
    "lamp":     ((1.00, 0.78, 0.52),  7.0, 0.60),
    "door":     ((1.00, 0.70, 0.42),  4.5, 0.50),
    "square":   ((1.00, 0.80, 0.58),  8.5, 0.65),
}

def light(x, y, z, color, radius, note, shadow=False, interior=False, room=None,
          soft=0.0):
    LIGHTS.append((x, y, z, color, radius, shadow, note, interior, room, soft))

def lamp(kind, x, y, z, note, radius=None, shadow=False, interior=False, room=None):
    """Огонь ИМЕНОВАННОГО ТИПА. Числа берутся из одной таблицы, а не пишутся у
    каждого вызова: разнообразие света — это шесть выдержанных типов, а не
    тридцать разных чисел, которые через неделю никто не сведёт."""
    col, rad, soft = LIGHT[kind]
    light(x, y, z, col, radius if radius is not None else rad, note,
          shadow=shadow, interior=interior, room=room, soft=soft)

# --- сетка высот двухпроходного цикла (gen -> dump_heights -> gen) ----------
HEIGHTS_PATH = os.environ.get("WHITERUN_HEIGHTS", "/tmp/whiterun_heights.txt")
_H = None
if os.path.exists(HEIGHTS_PATH):
    _H = [[float(v) for v in line.split()]
          for line in open(HEIGHTS_PATH, encoding="utf-8") if not line.startswith("#")]

def ground(x, z):
    if _H is None:
        return None
    xi = min(max(x, 0.0), 254.999)
    zi = min(max(z, 0.0), 254.999)
    x0, z0 = int(xi), int(zi)
    fx, fz = xi - x0, zi - z0
    r0, r1 = _H[z0], _H[z0 + 1]
    return ((r0[x0]*(1-fx) + r0[x0+1]*fx) * (1-fz)
            + (r1[x0]*(1-fx) + r1[x0+1]*fx) * fz)

def sit(x, z, fallback, half=3.5):
    gs = [ground(x+dx, z+dz) for dx, dz in
          ((0,0),(half,half),(half,-half),(-half,half),(-half,-half))]
    gs = [g for g in gs if g is not None]
    return fallback if not gs else min(gs) - 0.05

def rect_points(cx, cz, w, d, yaw_deg, n=5):
    """Сетка n x n по ПОВЁРНУТОМУ пятну здания."""
    c = math.cos(math.radians(yaw_deg))
    sn = math.sin(math.radians(yaw_deg))
    out = []
    for i in range(n):
        lx = (-0.5 + i/(n-1)) * w
        for j in range(n):
            lz = (-0.5 + j/(n-1)) * d
            out.append((cx + lx*c + lz*sn, cz - lx*sn + lz*c))
    return out

def sit_rect(cx, cz, w, d, yaw_deg, fallback):
    """Посадка по МИНИМУМУ ПЯТНА, и пятно берётся повёрнутым. Прежняя проба
    «центр плюс четыре угла квадрата half=max(w,d)/2» для замка 26.6х14
    щупала землю в 18 м от центра — за кромкой замкового плато, и находила
    там 25 вместо 36: замок стоял закопанным по конёк одиннадцать метров."""
    gs = [g for g in (ground(px, pz) for px, pz in rect_points(cx, cz, w, d, yaw_deg))
          if g is not None]
    return fallback if not gs else min(gs) - 0.05

# --- kind -> рецепт и ЗАМЕРЕННЫЕ габариты (фронт w вдоль двери, глубина d) --
# Числа сняты с самих .dfh (габарит вершин), а не выписаны на глаз: прежняя
# таблица давала city-house-s 7х7 при факте 4.5х6.0 и city-longhall 12х8 при
# факте 16х8 — расстановка считала Йоррваскр на 4 м короче, чем он есть, а
# дворовый клаттер садился бы в стену. Габарит берётся ПО КОРПУСУ вместе с
# навесом/портиком: они тоже занимают землю.
KIND = {
    "keep":    "city-keep-s.dfh",
    "wing":    None,  # крылья входят в рецепт keep-s
    "donjon":  "city-donjon.dfh",
    # city-manor реально 14х15 с крылом — на схемном пятне 9х7 крыло легло
    # на главную улицу (прогон v5-1). Усадьба плана = крупный дом.
    "manor":   "city-house-l.dfh",
    "temple":  "city-temple.dfh",
    "longhall":"city-longhall.dfh",
    "shop":    "city-shop.dfh",
    "tavern":  "city-house-l.dfh",
    "smithy":  "city-shop-old.dfh",
    "old":     "city-house-s-old.dfh",
    "farm":    "city-house-s.dfh",
    "barn":    "city-barn.dfh",
    "mill":    "city-mill.dfh",
    "stable":  "city-barn-old.dfh",
    "inn":     "city-house-l.dfh",
    "":        "city-house-s.dfh",
}

_REC = {}

def recipe_box(rec):
    """ГАБАРИТ И ДВЕРЬ РЕЦЕПТА СНИМАЮТСЯ С САМОГО .dfh, а не пишутся в
    таблицу: (центр габарита в локали, w, d, ось двери, вынос двери от
    центра). Таблица чисел «на глаз» уже дала city-house-s 7х7 при факте
    4.5х6.0 и Йоррваскр на 4 м короче своего тела; кузница мебели к тому же
    перепекает рецепты каждую волну, и любая переписанная цифра — будущая
    ложь. ОСЬ ДВЕРИ ВАЖНА ОТДЕЛЬНО: put_house считал, что дверь всегда на
    стороне z=d, а у city-longhall она на x=w и у city-mill на x=0 — обе
    постройки стояли к своей улице глухой стеной, повёрнутые на 90 гр. от
    красной стрелки чертежа (Йоррваскр — одна из четырёх названных доминант
    гайда §11). Дверь узнаётся по атрибуту door=1; у ворот амбара его нет —
    им остаётся сторона z=d."""
    if rec in _REC:
        return _REC[rec]
    V, door = {}, None
    for line in open(os.path.join(ROOT, "assets/houses", rec), encoding="utf-8"):
        t = line.split()
        if not t:
            continue
        if t[0] == "vertex":
            V[t[1]] = (float(t[3]), float(t[5]))
        elif "door=1" in line:
            pts = [V[v] for v in t[2:] if v in V]
            if pts:
                door = (sum(p[0] for p in pts)/len(pts),
                        sum(p[1] for p in pts)/len(pts))
    xs = [p[0] for p in V.values()]
    zs = [p[1] for p in V.values()]
    cx, cz = (min(xs)+max(xs))/2, (min(zs)+max(zs))/2
    w, d = max(xs)-min(xs), max(zs)-min(zs)
    if door is None:
        axis, off = "+Z", d/2
    else:
        dxl, dzl = door[0]-cx, door[1]-cz
        if abs(dzl) >= abs(dxl):
            axis, off = ("+Z", dzl) if dzl > 0 else ("-Z", -dzl)
        else:
            axis, off = ("+X", dxl) if dxl > 0 else ("-X", -dxl)
    _REC[rec] = (cx, cz, w, d, axis, off)
    return _REC[rec]

_TOP = {}

def recipe_top(rec):
    """ВЕРХ ТЕЛА РЕЦЕПТА, замеренный, а не выписанный: у стенки .dfh верх
    лежит не на вершине, а на «вершина + height», и разница как раз та, из-за
    которой огонь оказывался ВНУТРИ своей же чаши (у очага вершины кончаются
    на 0.17, а борт лотка — на 0.38)."""
    if rec in _TOP:
        return _TOP[rec]
    V, top = {}, 0.0
    for line in open(os.path.join(ROOT, "assets/houses", rec), encoding="utf-8"):
        t = line.split()
        if not t:
            continue
        if t[0] == "vertex":
            V[t[1]] = float(t[4])
            top = max(top, V[t[1]])
        elif t[0] == "surface":
            h = 0.0
            for tok in t:
                if tok.startswith("height="):
                    h = float(tok.split("=")[1])
            ys = [V[v] for v in t[2:] if v in V]
            if ys:
                top = max(top, max(ys) + h)
    _TOP[rec] = top
    return top

def yaw_for_door(axis, dx, dz):
    """yaw сцены, при котором наружная нормаль двери рецепта смотрит в (dx,dz).
    Конвенция: +X_лок = (cos, -sin), +Z_лок = (sin, cos)."""
    if axis == "+Z":
        return math.degrees(math.atan2(dx, dz)) % 360.0
    if axis == "-Z":
        return math.degrees(math.atan2(-dx, -dz)) % 360.0
    if axis == "+X":
        return math.degrees(math.atan2(-dz, dx)) % 360.0
    return math.degrees(math.atan2(dz, -dx)) % 360.0

